-- Seed finalisasi 20 Agustus 2026. Jalankan setelah schema.sql.
begin;


on conflict(code) do update set name=excluded.name, slug=excluded.slug;

on conflict(task_key) do update set title=excluded.title,description=excluded.description,source_url=excluded.source_url,source_spreadsheet_id=excluded.source_spreadsheet_id,source_sheet=excluded.source_sheet,source_letter=excluded.source_letter,due_date=excluded.due_date,due_label=excluded.due_label,sync_config=excluded.sync_config;

-- Requirements: plang-rumah

-- Requirements: xray

-- Requirements: master-aset

-- Requirements: rkbmn

-- Requirements: persediaan-rusak

-- Assignments: plang-rumah

-- Assignments: xray

-- Assignments: master-aset

-- Assignments: rkbmn

-- Assignments: persediaan-rusak

-- Pekerjaan: Pemusnahan Persediaan Usang
with r(k,l,o) as (values ('surat_permohonan','Surat Permohonan Satker',1),('sk_tim_pemusnahan','SK Tim Pemusnahan',2),('sptjm','SPTJM',3),('tidak_ganggu_tusi','Surat Pernyataan Tidak Mengganggu Tusi',4),('berita_acara','Berita Acara Penelitian Persediaan',5),('daftar_persediaan','Cetakan Daftar Persediaan Usang/Rusak',6),('dokumentasi','Dokumentasi BMN Terkini',7),('telaah_staf','Telaah Staf',8)) insert into public.task_requirements(task_id,requirement_key,label,track,display_order) select t.id,r.k,r.l,'Data Dukung',r.o from r cross join public.tasks t where t.task_key='persediaan-usang' on conflict(task_id,requirement_key) do update set label=excluded.label,display_order=excluded.display_order;
with a(code) as (values ('692308'),('692309'),('692311'),('692312'),('692314'),('692315'),('692316'),('692317'),('692484'),('692519'),('692537'),('692781'),('692794')) insert into public.task_assignments(task_id,satker_id,progress,status,missing,last_synced_at) select t.id,s.id,100,'persetujuan','[]'::jsonb,now() from a join public.satkers s on s.code=a.code cross join public.tasks t where t.task_key='persediaan-usang' on conflict(task_id,satker_id) do update set progress=100,status='persetujuan',missing='[]'::jsonb,last_synced_at=now();

commit;
